<script lang="ts">
 let {rows,columns,t,lang='de',timezone='Europe/Berlin',collection=''}:{lang?:string;timezone?:string;collection?:string;rows:Record<string,any>[];columns:string[];t:(key:string)=>string}=$props();let extra=$state<Record<string,any>[]>([]),filter=$state(''),busy=$state(false),done=$state(false),message=$state('');let all=$derived([...rows,...extra]),visible=$derived(all.filter(r=>!filter||columns.some(k=>String(r[k]??'').toLocaleLowerCase().includes(filter.toLocaleLowerCase()))));
 $effect(()=>{void rows;extra=[];done=false;});
 async function more(){busy=true;try{const res=await fetch('/api/read?collection='+encodeURIComponent(collection)+'&limit=500&cursor='+btoa(String(all.length)).replaceAll('=',''));const result=await res.json();if(res.ok){extra=[...extra,...result.rows];done=!result.next_cursor;}else message=t(result.message);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 function value(v:any,key:string){if(typeof v==='boolean')return t(v?'yes':'no');if(v===null||v===undefined)return '—';if(typeof v==='object')return JSON.stringify(v);const text=String(v);if(/(?:_l|_ha|_kg|_ml)$/.test(key)||['cost_per_l','value','percentage','amount','actual_cost','planned_cost','allocated_cost','cost_per_unit','available','total_actual','total_planned','base_wine_cost','actual_per_l','actual_per_bottle'].includes(key)){const n=Number(text);if(Number.isFinite(n))return new Intl.NumberFormat(lang,{maximumFractionDigits:key.includes('cost')||key==='amount'?2:key==='value'?6:key==='area_ha'?4:3}).format(n);}if(/^\d{4}-\d{2}-\d{2}T\d{2}:/.test(text))return new Intl.DateTimeFormat(lang,{dateStyle:'short',timeStyle:'short',timeZone:timezone}).format(new Date(text));return text==='ph'?'pH':key==='kind'&&text==='bottle'?t('bottle_item'):t(text);}
</script>
{#if rows.length}<label>{t('filterTable')}<input type="search" bind:value={filter} /></label><div class="scroll"><table><thead><tr>{#each columns as key}<th>{t(key)}</th>{/each}</tr></thead><tbody>{#each visible as row}<tr>{#each columns as key}<td title={String(row[key]??'')}>{value(row[key],key)}</td>{/each}</tr>{/each}</tbody></table></div>{#if collection&&rows.length===500&&!done}<button onclick={more} disabled={busy}>{t('loadMore')}</button>{/if}{:else}<p class="muted">{t('empty')}</p>{/if}<p role="status">{message}</p>
<style>input{margin-bottom:10px;max-width:300px}.scroll{overflow:auto;max-height:480px}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left;white-space:nowrap}th{color:#63735e;font-size:11px;font-weight:500;padding:10px 14px;border-bottom:1px solid #dce4d6;position:sticky;top:0;background:white}td{padding:13px 14px;border-bottom:1px solid #edf0e8;max-width:320px;overflow:hidden;text-overflow:ellipsis}tbody tr:hover{background:#f8faf4}button{margin-top:12px}</style>
